import { motion } from "motion/react"

import { cn } from "@/lib/utils"
import type { BackgroundGradientProps } from "@/components/ui/background-gradient-types"

const gradientVariants = {
  initial: { backgroundPosition: "0% 50%" },
  animate: { backgroundPosition: ["0% 50%", "100% 50%", "0% 50%"] },
}

const gradientTransition = {
  duration: 5,
  repeat: Infinity,
  repeatType: "reverse",
} as const

function BackgroundGradient({
  children,
  className,
  containerClassName,
  animate = true,
  ...rest
}: BackgroundGradientProps) {
  return (
    <div
      data-slot="background-gradient"
      className={cn("group relative p-[4px]", containerClassName)}
      {...rest}
    >
      <motion.div
        variants={animate ? gradientVariants : undefined}
        initial={animate ? "initial" : undefined}
        animate={animate ? "animate" : undefined}
        transition={animate ? gradientTransition : undefined}
        style={{ backgroundSize: animate ? "400% 400%" : undefined }}
        className={cn(
          "absolute inset-0 z-[1] rounded-3xl opacity-60 blur-xl transition duration-500 will-change-transform group-hover:opacity-100",
          "bg-[radial-gradient(circle_farthest-side_at_0_100%,#00ccb1,transparent),radial-gradient(circle_farthest-side_at_100%_0,#7b61ff,transparent),radial-gradient(circle_farthest-side_at_100%_100%,#ffc414,transparent),radial-gradient(circle_farthest-side_at_0_0,#1ca0fb,#141316)]"
        )}
      />
      <motion.div
        variants={animate ? gradientVariants : undefined}
        initial={animate ? "initial" : undefined}
        animate={animate ? "animate" : undefined}
        transition={animate ? gradientTransition : undefined}
        style={{ backgroundSize: animate ? "400% 400%" : undefined }}
        className={cn(
          "absolute inset-0 z-[1] rounded-3xl will-change-transform",
          "bg-[radial-gradient(circle_farthest-side_at_0_100%,#00ccb1,transparent),radial-gradient(circle_farthest-side_at_100%_0,#7b61ff,transparent),radial-gradient(circle_farthest-side_at_100%_100%,#ffc414,transparent),radial-gradient(circle_farthest-side_at_0_0,#1ca0fb,#141316)]"
        )}
      />
      <div className={cn("relative z-10", className)}>{children}</div>
    </div>
  )
}

export { BackgroundGradient }

import * as React from "react"

/**
 * Tipos do Background Gradient (Aceternity UI), reimplementado padronizado shadcn.
 *
 * Mantido em arquivo separado (.ts puro, sem JSX) para satisfazer o
 * react-refresh/only-export-components (o .tsx só exporta componentes).
 */
export interface BackgroundGradientProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  children?: React.ReactNode
  /** Classe do wrapper de conteúdo interno (relative z-10). */
  className?: string
  /** Classe do container raiz que recebe os gradientes. */
  containerClassName?: string
  /** Anima a posição dos gradientes em loop. Default: true. */
  animate?: boolean
}
